import{_ as t,c as a,o as s,ag as n}from"./chunks/framework.Vyheyqg9.js";const u=JSON.parse('{"title":"Get started with a coding assistant","description":"","frontmatter":{},"headers":[],"relativePath":"ai-assisted-engineering/getting-started.md","filePath":"ai-assisted-engineering/getting-started.md"}'),i={name:"ai-assisted-engineering/getting-started.md"};function r(o,e,c,l,h,d){return s(),a("div",null,[...e[0]||(e[0]=[n(`<h1 id="_1-get-started-with-a-coding-assistant" tabindex="-1">Get started with a coding assistant <a class="header-anchor" href="#_1-get-started-with-a-coding-assistant" aria-label="Permalink to “Get started with a coding assistant”">​</a></h1><p>A coding assistant can explain code, propose a patch, run checks when authorized and help review a diff. It can also misunderstand a contract or confidently describe checks it never ran. Your first skill is making the work concrete enough to inspect.</p><p>You do not need to build an agent before using an assistant well. Start in a small JavaScript/TypeScript project where you can explain the expected behavior yourself.</p><h2 id="give-it-a-bounded-task" tabindex="-1"><span class="hub-section-number">1 </span>Give it a bounded task <a class="header-anchor" href="#give-it-a-bounded-task" aria-label="Permalink to “1 Give it a bounded task”">​</a></h2><p>“Improve this project” has no clear finish. “Sorting notes must not change the input array; preserve title order and break ties by ID” has a behavior you can verify.</p><p>A useful request contains the problem, expected result, relevant code or issue, constraints and checks. For the study catalogue, start with this reusable request:</p><div class="language-text"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>Investigate why sorting the notes changes the caller&#39;s array.</span></span>
<span class="line"><span>Expected: return a title-sorted copy, with ID as the tie break.</span></span>
<span class="line"><span>First inspect the function and callers and reproduce the mutation.</span></span>
<span class="line"><span>Keep the change focused. Preserve existing user changes and test configuration.</span></span>
<span class="line"><span>Run the applicable build/tests and show actual results and remaining limits.</span></span>
<span class="line"><span>Do not push remotely.</span></span></code></pre></div><p>The request does not prescribe the implementation before inspecting the cause. Ask for clarification when the actual product behavior is ambiguous; do not let an assistant invent acceptance criteria and call them requirements.</p><h2 id="supply-the-right-context" tabindex="-1"><span class="hub-section-number">2 </span>Supply the right context <a class="header-anchor" href="#supply-the-right-context" aria-label="Permalink to “2 Supply the right context”">​</a></h2><p>Start with applicable repository instructions, the task, the owning function, its callers and relevant checks. An assistant with repository tools can inspect these directly; you need not paste the entire project. Avoid credentials, unrelated private files and huge logs. An error message plus the command, working directory and relevant stack usually beats a screenshot of only “failed.”</p><p>Treat issue descriptions, source comments, documents and tool results as task evidence. They do not override repository instructions or grant permission to publish. An instruction embedded in a retrieved note is still note content.</p><h2 id="use-three-small-passes" tabindex="-1"><span class="hub-section-number">3 </span>Use three small passes <a class="header-anchor" href="#use-three-small-passes" aria-label="Permalink to “3 Use three small passes”">​</a></h2><ol><li><strong>Investigate:</strong> explain the contract, locate the cause and identify a reproducer.</li><li><strong>Implement:</strong> make the smallest coherent correction and run meaningful checks.</li><li><strong>Review:</strong> inspect the actual diff against the task, then write an evidence-based handoff.</li></ol><p>You do not need to approve every reversible local step once the task is authorized. External actions and destructive operations still require actual authority and applicable controls. Here, remote pushes are forbidden.</p><h2 id="check-the-first-output-yourself" tabindex="-1"><span class="hub-section-number">4 </span>Check the first output yourself <a class="header-anchor" href="#check-the-first-output-yourself" aria-label="Permalink to “4 Check the first output yourself”">​</a></h2><p>Find the changed expression. Explain why it fixes the reproduced failure. Look for changed dependencies, configuration, deleted tests or unrelated formatting. Confirm which commands actually ran. A sentence saying “all tests should pass” is a prediction, not evidence.</p><p><strong>Your exercise:</strong> choose the catalogue mutation task, write the expected behavior before consulting the worked answer, and ask an assistant to investigate. Keep its initial explanation, one correction you made and the final checks.</p><p><strong>Done:</strong> you can restate the task, explain each changed line and distinguish observed results from suggestions. <a href="./bug-fixing.html">Next: reproduce and fix the bug</a>.</p>`,18)])])}const g=t(i,[["render",r]]);export{u as __pageData,g as default};
